def is_valid_n_queens(n, board):
    if len(board) != n:
        return False

    # Check rows (already satisfied by the structure)
    # Check columns
    if len(set(board)) != n:
        return False

    # Check diagonals
    for i in range(n):
        for j in range(i + 1, n):
            if abs(board[i] - board[j]) == abs(i - j):
                return False
    return True

